-- One View Records grant per resource. Credential hashes and business records are untouched.
alter table feedx_integrations.resources add column dependencies jsonb not null default '[]', add column relationship_fields jsonb not null default '{}', add column date_semantics text not null default 'Malaysia business dates; live saved lifecycle, not a historical reconstruction.';
alter table feedx_integrations.capabilities drop constraint capabilities_action_type_check;
alter table feedx_integrations.capabilities add constraint capabilities_action_type_check check(action_type in ('view','list','read','search','filter','draft','execute','approve'));
update feedx_integrations.adapters set scope='Factory records · read only' where key='factory_mesti';
update public.permissions set description='Connect to the Factory External Agent Gateway; each resource requires its own grant.' where code='factory_mesti_inspection.view';


