-- Preserve partially granted old operations without promoting them to View Records.
insert into public.role_permissions(role_id,permission_id)
select rp.role_id,p.id from feedx_integrations.resources r join feedx_integrations.capabilities c on c.resource_key=r.key and c.action_type in ('list','read','search','filter') join public.permissions op on op.code=c.permission_code join public.role_permissions rp on rp.permission_id=op.id join public.permissions p on p.code='factory_agent_'||r.slug||'.view'
group by rp.role_id,p.id having count(distinct c.action_type)=4 on conflict do nothing;
delete from public.role_permissions rp using public.permissions p where p.id=rp.permission_id and p.code like 'factory_mesti_resource_%.%' and exists(select 1 from public.role_permissions fullgrant join public.permissions vp on vp.id=fullgrant.permission_id where fullgrant.role_id=rp.role_id and vp.code='factory_agent_'||split_part(replace(p.code,'factory_mesti_resource_',''),'.',1)||'.view');
-- Only the union of all five review grants is equivalent to the review resource.
insert into public.role_permissions(role_id,permission_id) select rp.role_id,p.id from public.role_permissions rp join public.permissions old on old.id=rp.permission_id cross join public.permissions p where old.code in ('factory_mesti_inspection_status.view','factory_mesti_inspection_exceptions.view','factory_mesti_inspection_verifications.view','factory_mesti_inspection_evidence.view','factory_mesti_inspection_schedule.view') and p.code='factory_agent_mesti_review.view' group by rp.role_id,p.id having count(distinct old.code)=5 on conflict do nothing;
insert into public.audit_logs(action,module,user_name,description,metadata) select 'external_agent_resource_migrated','access-control','Gateway migration','Equivalent MeSTI review access migrated; credential unchanged.',jsonb_build_object('identity_id',m.id,'role_id',m.role_id,'label','Compliance review records','scope_expanded',false) from feedx_integrations.machine_identities m join public.role_permissions rp on rp.role_id=m.role_id join public.permissions p on p.id=rp.permission_id where p.code='factory_agent_mesti_review.view';
delete from public.role_permissions rp using public.permissions p where p.id=rp.permission_id and p.code in ('factory_mesti_inspection_status.view','factory_mesti_inspection_exceptions.view','factory_mesti_inspection_verifications.view','factory_mesti_inspection_evidence.view','factory_mesti_inspection_schedule.view') and exists(select 1 from public.role_permissions fullgrant join public.permissions vp on vp.id=fullgrant.permission_id where fullgrant.role_id=rp.role_id and vp.code='factory_agent_mesti_review.view');


create or replace function feedx_integrations.resource_authorize(p_token text,p_resource text,p_action text) returns uuid language plpgsql stable security definer set search_path=public,pg_temp as $$
declare v_id uuid;v_permission text;dep text;
begin
 v_id:=feedx_integrations.authorize(p_token,'factory_mesti_inspection.view');
 if p_action is null or p_action not in ('list','read','search','filter') then raise exception using errcode='42501',message='Read operation denied.';end if;
 select c.permission_code into v_permission from feedx_integrations.machine_identities m join feedx_integrations.resources r on r.adapter_key=m.adapter_key join feedx_integrations.capabilities c on c.resource_key=r.key where m.id=v_id and r.slug=p_resource and r.implemented and c.implemented and c.action_type='view' and not c.requires_human_approval;
 if v_permission is null then raise exception using errcode='42501',message='Resource denied.';end if;
 if not exists(select 1 from feedx_integrations.machine_identities m join public.role_permissions rp on rp.role_id=m.role_id join public.permissions p on p.id=rp.permission_id where m.id=v_id and p.code=v_permission) then
  -- Compatibility for partial operation grants predating View Records. Never assignable in the new selector.
  select c.permission_code into v_permission from feedx_integrations.capabilities c join feedx_integrations.resources r on r.key=c.resource_key where r.slug=p_resource and c.action_type=p_action and c.mcp_tool='query_mesti_resources';
  if v_permission is null then raise exception using errcode='42501',message='View Records denied.';end if;
 end if;
 perform feedx_integrations.authorize(p_token,v_permission);
 for dep in select jsonb_array_elements_text(dependencies) from feedx_integrations.resources where slug=p_resource loop perform feedx_integrations.resource_authorize(p_token,dep,'list');end loop;
 return v_id;
end $$;
create function feedx_integrations.has_resource(p_token text,p_resource text) returns boolean language plpgsql stable security definer set search_path=public,pg_temp as $$ begin perform feedx_integrations.resource_authorize(p_token,p_resource,'list');return true;exception when insufficient_privilege then return false;end $$;
revoke all on function feedx_integrations.has_resource(text,text) from public,anon,authenticated;


create function feedx_integrations.read_permission(p_token text,p_permission text) returns boolean language plpgsql stable security invoker set search_path=public,pg_temp as $$ declare r text;begin if p_token is null then return public.current_user_has_permission(p_permission);end if; r:=case p_permission when 'factory_dashboard.view' then 'dashboard' when 'factory_production.view' then 'production_records' when 'factory_production_reports.view' then 'production_records' when 'factory_job_orders.view' then 'job_orders' when 'factory_finished_goods_dispatch.view' then 'dispatches' when 'factory_raw_receiving.view' then 'receipts' when 'factory_raw_inventory.view' then 'raw_materials' when 'factory_finished_goods.view' then 'finished_goods' when 'factory_batch_traceability.view' then 'traceability' when 'factory_raw_stock_check.view' then 'raw_stock_checks' when 'factory_product_stock_check.view' then 'product_stock_checks' end; if r is null then return false;end if; return feedx_integrations.has_resource(p_token,r);end $$;

grant usage on schema feedx_integrations to authenticated; grant execute on function feedx_integrations.read_permission(text,text) to authenticated;

do $move$ declare b text;l text;begin select prosrc,lanname into b,l from pg_proc p join pg_language lang on lang.oid=p.prolang where p.oid='public.factory_get_dashboard_monthly_analytics(date,uuid)'::regprocedure;
 b:=replace(b,'auth.uid() is null','(auth.uid() is null and p_gateway_token is null)');
 b:=regexp_replace(b,'public.current_user_has_permission\(', 'feedx_integrations.read_permission(p_gateway_token,','g');
 b:=replace(b,'public.factory_get_dashboard_monthly_analytics(p_month, p_finished_good_id, p_include_operational_comparisons)','feedx_integrations.factory_get_dashboard_monthly_analytics_core(p_month, p_finished_good_id, p_include_operational_comparisons,p_gateway_token)');
 b:=replace(b,'public.factory_get_dashboard_monthly_analytics(p_month, p_finished_good_id)','feedx_integrations.factory_get_dashboard_monthly_analytics_core(p_month, p_finished_good_id,p_gateway_token)');
